/* @autogenerated */
import { translocoConfig } from '@jsverse/transloco';
import { rootLogger } from '@shared/context/observability/logger.service';
import { HumanizingMissingHandler, humanizeKey } from './missing-handler';

describe('humanizeKey', () => {
  it('skips generic trailing segments', () => {
    expect(humanizeKey('allow-all-scopes.title')).toBe('Allow all scopes');
    expect(humanizeKey('access.oauth-client.list.filter.button')).toBe('Filter');
  });

  it('uses the last segment when it is meaningful', () => {
    expect(humanizeKey('common.actions.save')).toBe('Save');
  });

  it('splits camelCase and snake_case', () => {
    expect(humanizeKey('form.redirectUris')).toBe('Redirect uris');
    expect(humanizeKey('form.client_secret.label')).toBe('Client secret');
  });

  it('ignores the scope prefix', () => {
    expect(humanizeKey('identity/tenant.list.title')).toBe('List');
  });

  it('falls back to the last segment when all of them are generic', () => {
    expect(humanizeKey('title')).toBe('Title');
    expect(humanizeKey('header.title')).toBe('Title');
  });

  it('never returns a key with dots', () => {
    expect(humanizeKey('a.b.c.label')).not.toContain('.');
  });
});

describe('HumanizingMissingHandler', () => {
  const data = (prodMode: boolean) => ({ ...translocoConfig({ prodMode }), activeLang: 'es' });
  let handler: HumanizingMissingHandler;
  let warn: jasmine.Spy;

  beforeEach(() => {
    handler = new HumanizingMissingHandler();
    warn = spyOn(rootLogger, 'warn');
  });

  it('humanizes the key in production without logging', () => {
    expect(handler.handle('allow-all-scopes.title', data(true))).toBe('Allow all scopes');
    expect(warn).not.toHaveBeenCalled();
  });

  it('marks the key in development and logs it only once', () => {
    expect(handler.handle('allow-all-scopes.title', data(false))).toBe('⟦allow-all-scopes.title⟧');
    handler.handle('allow-all-scopes.title', data(false));
    expect(warn).toHaveBeenCalledTimes(1);
  });
});
